set -eu
test "$(git rev-parse HEAD)" = "0d11477f61837c3da7da42393daa1bf04b01088e"
git fetch --no-tags origin refs/heads/fix/debugai-scout-diagnosis-handoff-20261016
test "$(git rev-parse FETCH_HEAD)" = "ac0a3c19c1670055711e2548f7da59e79310400e"
python3 -B - <<'PY'
import subprocess,json
source=subprocess.check_output(["git","show","ac0a3c19c1670055711e2548f7da59e79310400e:server/control/role-prompt-evidence.js"],text=True)
node=r'''
const fs=require("node:fs"),path=require("node:path"),assert=require("node:assert/strict"),Module=require("node:module");
const root="/app",runId="run_mwyq6tsz_e40f80d39b",repo="/workspace/debug-ai/.verification/real-debug/realdebug_6d6055e23feb47868406cc577b8958ca/L1-01";
